"""Tests for soft-label distillation (drift.hybrid.distill)."""

import numpy as np
import pytest

from drift.hybrid.distill import (
    expected_calibration_error,
    softmax,
    train_soft_student,
)


def _teacher_problem(n=200, d=8, seed=0):
    """Features + a known teacher distribution generated by a linear model."""
    rng = np.random.default_rng(seed)
    X = rng.normal(0, 1, (n, d)).astype(np.float32)
    W = np.array([[1.5, -0.5] + [0.0] * (d - 2),
                  [-1.5, 0.5] + [0.0] * (d - 2),
                  [0.0, 0.0, 2.0] + [0.0] * (d - 3)], dtype=np.float32)
    b = np.array([0.1, -0.1, 0.0], dtype=np.float32)
    teacher_probs = softmax(X @ W.T + b)
    return X, teacher_probs


class TestSoftmax:
    def test_rows_sum_to_one(self):
        z = np.array([[1.0, 2.0, 3.0], [100.0, 100.0, 100.0]])
        p = softmax(z)
        np.testing.assert_allclose(p.sum(axis=1), 1.0, rtol=1e-6)

    def test_numerically_stable(self):
        p = softmax(np.array([[1000.0, 1000.0]]))
        assert not np.isnan(p).any()


class TestTrainSoftStudent:
    def test_recovers_teacher_distribution(self):
        X, teacher = _teacher_problem()
        student = train_soft_student(X, teacher, epochs=800, lr=0.5)
        pred = softmax(X @ np.array(student["weights"]).T + np.array(student["bias"]))
        kl = np.mean(np.sum(
            teacher * (np.log(teacher + 1e-12) - np.log(pred + 1e-12)), axis=1))
        assert kl < 0.01, f"student KL {kl} too high"

    def test_temperature_softens_targets(self):
        X, teacher = _teacher_problem()
        s_hot = train_soft_student(X, teacher, temperature=1.0, epochs=200)
        s_soft = train_soft_student(X, teacher, temperature=4.0, epochs=200)
        # Higher temperature -> softer targets -> lower-magnitude weights
        norm_hot = np.linalg.norm(np.array(s_hot["weights"]))
        norm_soft = np.linalg.norm(np.array(s_soft["weights"]))
        assert norm_soft < norm_hot

    def test_hard_labels_accepted(self):
        X, teacher = _teacher_problem()
        y_hard = teacher.argmax(axis=1)
        onehot = np.eye(teacher.shape[1])[y_hard]
        student = train_soft_student(X, onehot, epochs=300, lr=0.5)
        pred = softmax(X @ np.array(student["weights"]).T + np.array(student["bias"]))
        acc = (pred.argmax(axis=1) == y_hard).mean()
        assert acc > 0.9


class TestECE:
    def test_perfectly_calibrated_is_low(self):
        # Confidence == accuracy by construction
        rng = np.random.default_rng(0)
        n = 4000
        conf = rng.uniform(0.5, 1.0, n)
        correct = rng.uniform(0, 1, n) < conf
        probs = np.stack([conf, 1 - conf], axis=1)
        y = np.where(correct, "a", "b")
        e = expected_calibration_error(probs, y, ["a", "b"])
        assert e < 0.05

    def test_overconfident_is_high(self):
        n = 1000
        probs = np.tile([0.99, 0.01], (n, 1))
        y = np.array(["a"] * (n // 2) + ["b"] * (n // 2))  # only 50% correct
        e = expected_calibration_error(probs, y, ["a", "b"])
        assert e > 0.4
